    [
        'slug' => 'air-duct-cleaning',
        'title' => 'Air Duct Cleaning',
        'nav_label' => 'Duct Cleaning',
        'group' => 'air',
        'icon' => 'air-vent',
        'image' => 'high-efficiency-gas-furnace.jpg',
